    for case in cases.as_array().unwrap() {
        let args: Vec<_> = case["args"]
            .as_array()
            .unwrap()
            .iter()
            .map(|s| s.as_str().unwrap())
            .collect();
        let input = case["input"].as_str().unwrap_or("");
        let got = common::dt_in(&args, input.as_bytes());
        assert_eq!(got.code, case["code"].as_i64().unwrap() as i32, "{args:?}: {}", got.err);
        let expected = case["out"].as_str().unwrap();
        if args.contains(&"--json") && got.code == 0 {
            let actual: serde_json::Value = serde_json::from_str(&got.out).unwrap();
            let expected: serde_json::Value = serde_json::from_str(expected).unwrap();
            assert_eq!(actual, expected, "{args:?}");
        } else {
            assert_eq!(got.out, expected, "{args:?}");
        }
        let err = case["err"].as_str().unwrap();
        if !err.contains("Unknown option")
            && !err.contains("does not take an argument")
            && !err.contains("requires an argument")
            && !err.contains("Option '")
        {
            assert_eq!(got.err, err, "{args:?}");
        }
    }
